// Shows remote worker progress on setup, live Studio and the saved reader.
import {LOAD_MESSAGES,engineScene} from './engine-monitor.js';
const token=localStorage.getItem('utility-local-workspace');
if(token){const style=document.createElement('link');style.rel='stylesheet';style.href='./local-runs.css';document.head.append(style);const host=document.createElement('aside');host.className='local-floating';host.hidden=true;host.setAttribute('role','status');document.body.append(host);const q=new URLSearchParams(location.search),api=(q.get('engine')||'').replace(/\/$/,'')+'/api';
 async function refresh(){try{const r=await fetch(api+'/portal/workspace',{headers:{Authorization:'Bearer '+token},signal:AbortSignal.timeout(8000)});if(!r.ok)return;const data=await r.json(),active=data.jobs.find(j=>['running','queued'].includes(j.status));host.hidden=!active;if(!active)return;const p=active.progress||{},url=new URL('./local-runs.html',location.href);url.searchParams.set('model',active.recipe.modelId);if(q.get('engine'))url.searchParams.set('engine',q.get('engine'));host.replaceChildren();const name=document.createElement('strong');name.textContent=active.recipe.name+' · revision '+active.revision;const phase=document.createElement('p');phase.textContent=active.status==='queued'?'Waiting for a connected computer':p.stage||'Preparing the engine';const counts=document.createElement('p');counts.textContent=`${p.completed||0}/${p.total||Math.ceil(active.recipe.homes/active.recipe.chunkSize)} districts · ${p.etaSeconds==null?'Estimating…':Math.ceil(p.etaSeconds/60)+' min remaining'}`;const note=document.createElement('small');note.textContent=LOAD_MESSAGES[Math.floor(Date.now()/7000)%LOAD_MESSAGES.length];const link=document.createElement('a');link.href=url.href;link.textContent='Open local run →';link.style.color='white';link.style.display='block';link.style.marginTop='10px';const scene=document.createElement('div');scene.innerHTML=engineScene(Math.floor(Date.now()/18000));scene.style.maxHeight='110px';scene.style.overflow='hidden';host.append(name,phase,counts,scene,note,link);host.style.bottom=document.querySelector('.engine-monitor.is-running')?'290px':'20px';}catch{}}
 refresh();setInterval(refresh,10000);
}
